import{_ as e,c as i,o as t,a2 as l}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"インストール","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/installation.md","filePath":"ja/guide/installation.md","lastUpdated":1793163976000}'),o={name:"ja/guide/installation.md"};function s(r,a,n,p,h,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h1><p>NueZip は Mac App Store を通じて macOS 向けに提供されています。</p><h2 id="ダウンロードオプション" tabindex="-1">ダウンロードオプション <a class="header-anchor" href="#ダウンロードオプション" aria-label="Permalink to &quot;ダウンロードオプション&quot;">​</a></h2><h3 id="mac-app-store-推奨" tabindex="-1">Mac App Store（推奨） <a class="header-anchor" href="#mac-app-store-推奨" aria-label="Permalink to &quot;Mac App Store（推奨）&quot;">​</a></h3><ul><li><strong>ダウンロード</strong>: <a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">Mac App Store の NueZip</a></li></ul><p>Mac App Store 版は自動更新と macOS とのシームレスな統合を提供します。</p><h3 id="github-releases-代替" tabindex="-1">GitHub Releases（代替） <a class="header-anchor" href="#github-releases-代替" aria-label="Permalink to &quot;GitHub Releases（代替）&quot;">​</a></h3><p>直接ダウンロードをご希望の場合は、<a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a> からアプリを取得できます。このバージョンは自動更新を受け取らないことに注意してください。</p><h2 id="インストール手順" tabindex="-1">インストール手順 <a class="header-anchor" href="#インストール手順" aria-label="Permalink to &quot;インストール手順&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>上のダウンロードリンクをクリックするか、Mac App Store で &quot;NueZip&quot; を検索してください</li><li>&quot;入手&quot; をクリックしてアプリをダウンロードする</li><li>アプリは自動的にダウンロードおよびインストールされます</li><li>アプリケーションフォルダまたは Launchpad から NueZip を起動する</li></ol><h3 id="github-releases" tabindex="-1">GitHub Releases <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;GitHub Releases&quot;">​</a></h3><ol><li>Releases ページから最新の <code>.dmg</code> をダウンロードする</li><li>ダウンロードした <code>.dmg</code> をダブルクリックして開く</li><li><code>NueZip.app</code> アイコンを <code>Applications</code> フォルダにドラッグする</li><li>マウントされたイメージを取り出し、<code>Applications</code> から <code>NueZip</code> を開く</li></ol><p>macOS がアプリの起動をブロックする場合（Gatekeeper）、<strong>システム設定 → プライバシーとセキュリティ</strong> を開き、NueZip の <strong>このまま開く</strong> をクリックするか、アプリを右クリックして <strong>開く</strong> を選択してください。</p><h2 id="初回起動" tabindex="-1">初回起動 <a class="header-anchor" href="#初回起動" aria-label="Permalink to &quot;初回起動&quot;">​</a></h2><p>NueZip を初めて起動すると、次のオンボーディングフローが案内されます：</p><ul><li><strong>フォルダアクセスの許可</strong>: NueZip が一般的なディレクトリ（ダウンロード、書類、デスクトップ）にアクセスできるようにする</li><li><strong>Finder 機能拡張の有効化</strong>: クイックなアーカイブ操作のための右クリックコンテキストメニューを有効にする</li></ul><p>プロンプトが表示されたら権限を許可してください。これらは <strong>システム設定 → プライバシーとセキュリティ</strong> でいつでも変更できます。</p><h2 id="アップデート" tabindex="-1">アップデート <a class="header-anchor" href="#アップデート" aria-label="Permalink to &quot;アップデート&quot;">​</a></h2><ul><li><strong>Mac App Store 版</strong>: アップデートは App Store によって自動的に処理されます</li><li><strong>GitHub Releases 版</strong>: 新しいリリースをダウンロードし、<code>Applications</code> 内のアプリを置き換えてください</li></ul><h2 id="アンインストール" tabindex="-1">アンインストール <a class="header-anchor" href="#アンインストール" aria-label="Permalink to &quot;アンインストール&quot;">​</a></h2><p>NueZip をアンインストールするには：</p><ol><li>NueZip を終了する</li><li><code>NueZip.app</code> を <code>Applications</code> からゴミ箱にドラッグする</li><li>（オプション）アプリのデータとログを削除する：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Logs/nuezip</span></span></code></pre></div><h2 id="システム要件" tabindex="-1">システム要件 <a class="header-anchor" href="#システム要件" aria-label="Permalink to &quot;システム要件&quot;">​</a></h2><ul><li><strong>macOS</strong>: Sonoma（14）以降推奨</li><li><strong>CPU</strong>: Apple Silicon（M シリーズ）または Intel（64-bit）</li><li><strong>メモリ</strong>: 最小 4GB、推奨 8GB</li><li><strong>ストレージ</strong>: 約 50 MB</li></ul><h2 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h2><p>インストール中に問題が発生した場合：</p><ul><li><strong>macOS がアプリをブロックする</strong>: <strong>システム設定 → プライバシーとセキュリティ</strong> を開き、NueZip の <strong>このまま開く</strong> をクリックする</li><li><strong>公証（Notarization）警告</strong>: Mac App Store から署名済み／公証済みのビルドをダウンロードする</li></ul><p>詳しくは <a href="./troubleshooting.html">トラブルシューティングガイド</a> を参照してください。</p>`,30)])])}const g=e(o,[["render",s]]);export{u as __pageData,g as default};
